    required int version,
    required String format,
    required String encoding,
    required String delimiter,
    required int itemCount,
    required String status,
    required bool downloadRequired,
    required ApiCatalogDownloadTarget? downloadTarget,
  }) : super(<String, Object?>{
         'cacheId': cacheId,
         'checksum': checksum,
         'generatedAtIso': generatedAtIso,
         'expiresAtIso': expiresAtIso,
         'schemaVersion': schemaVersion,
         'version': version,
         'format': format,
         'encoding': encoding,
         'delimiter': delimiter,
         'itemCount': itemCount,
         'status': status,
         'downloadRequired': downloadRequired,
         'downloadTarget': downloadTarget?.toJson(),
       }) {
    if (!RegExp(r'^[a-fA-F0-9]{64}$').hasMatch(checksum)) {
      throw const FormatException(
        'Invalid ApiCatalogCacheData.checksum format.',
      );
    }
    if (schemaVersion < 1) {
      throw const FormatException(
        'ApiCatalogCacheData.schemaVersion is below its minimum.',
      );
    }
    if (version < 1) {
      throw const FormatException(
        'ApiCatalogCacheData.version is below its minimum.',
      );
    }
    if (!<String>{'csv'}.contains(format)) {
      throw const FormatException('Unknown ApiCatalogCacheData.format.');
    }
    if (!<String>{'utf-8'}.contains(encoding)) {
      throw const FormatException('Unknown ApiCatalogCacheData.encoding.');
    }
    if (!<String>{','}.contains(delimiter)) {
      throw const FormatException('Unknown ApiCatalogCacheData.delimiter.');
    }
    if (itemCount < 0) {
      throw const FormatException(
        'ApiCatalogCacheData.itemCount is below its minimum.',
      );
    }
    if (!<String>{'ready'}.contains(status)) {
      throw const FormatException('Unknown ApiCatalogCacheData.status.');
    }
    if (downloadRequired != (downloadTarget != null)) {
      throw const FormatException(
        'Download destination and required flag disagree.',
