/// Public observation record without private attributes.
///
/// Ignores unknown input members; owns collections and serializes canonical types.
class ApiObservation extends ApiValue {
  ApiObservation({
    required String id,
    required String schoolStoreId,
    required String studentSnapshotId,
    required String observationKind,
    required String severity,
    required String status,
    required String visibility,
    required String title,
    required String body,
    required String resolutionSummary,
    required ApiObservationContext context,
    required ApiSchoolAuthor author,
    required String createdAtIso,
    required String updatedAtIso,
  }) : super(<String, Object?>{
         'id': id,
         'schoolStoreId': schoolStoreId,
         'studentSnapshotId': studentSnapshotId,
         'observationKind': observationKind,
         'severity': severity,
         'status': status,
         'visibility': visibility,
         'title': title,
         'body': body,
         'resolutionSummary': resolutionSummary,
         'context': context.toJson(),
         'author': author.toJson(),
         'createdAtIso': createdAtIso,
         'updatedAtIso': updatedAtIso,
       }) {
    if (!<String>{
      'academic',
      'coexistence',
      'attendanceFollowUp',
      'general',
    }.contains(observationKind)) {
      throw const FormatException('Unknown ApiObservation.observationKind.');
    }
    if (!<String>{'info', 'low', 'medium', 'high'}.contains(severity)) {
      throw const FormatException('Unknown ApiObservation.severity.');
    }
    if (!<String>{
      'open',
      'inReview',
      'resolved',
      'archived',
    }.contains(status)) {
      throw const FormatException('Unknown ApiObservation.status.');
    }
    if (!<String>{'internal', 'restricted'}.contains(visibility)) {
      throw const FormatException('Unknown ApiObservation.visibility.');
    }
    if (!DateTimeIsoUtils.isCanonicalUtcIso(createdAtIso)) {
      throw const FormatException(
        'Invalid canonical UTC ApiObservation.createdAtIso.',
      );
    }
    if (!DateTimeIsoUtils.isCanonicalUtcIso(updatedAtIso)) {
      throw const FormatException(
        'Invalid canonical UTC ApiObservation.updatedAtIso.',
      );
    }
  }

  factory ApiObservation.fromJson(Map<String, Object?> json) {
    if (!json.containsKey('id')) {
      throw const FormatException('Missing ApiObservation.id.');
    }
    if (!json.containsKey('schoolStoreId')) {
      throw const FormatException('Missing ApiObservation.schoolStoreId.');
