      'certificate',
      'material',
      'other',
    }.contains(serviceKey)) {
      throw const FormatException(
        'Unknown ApiStudentPaymentReferenceInput.serviceKey.',
      );
    }
    if (!RegExp(r'^[0-9]{4}-(0[1-9]|1[0-2])$').hasMatch(academicPeriodKey)) {
      throw const FormatException(
        'Invalid ApiStudentPaymentReferenceInput.academicPeriodKey format.',
      );
    }
    if (label.isPresent &&
        label.value != null &&
