        label.value != null &&
        _containsActiveMarkup(label.value!)) {
      throw const FormatException(
        'Prohibited active markup in ApiStudentPaymentReferenceInput.label.',
      );
    }
    if (label.isPresent &&
        label.value != null &&
        RegExp(r'[<>]').hasMatch(label.value!)) {
      throw const FormatException(
        'Prohibited angle bracket in ApiStudentPaymentReferenceInput.label.',
      );
    }
    if (label.isPresent &&
        label.value != null &&
        RegExp(
          r'(password|token|legalId|correctAnswer)',
          caseSensitive: false,
        ).hasMatch(label.value!)) {
      throw const FormatException(
        'Prohibited label content in ApiStudentPaymentReferenceInput.label.',
